def expected_norm(dim,coo = corr0_999):
    return sqrt(dim * tau * coo)

def account_for_extraction(norm):
    return norm * 8 * gamma

def with_dropped_bits(norm, d, r, coo = corr0_999, height=1):
    return sqrt(norm^2 + height * phi * r * tau * (4^d - 1) / 12 * coo)
